mapper.select:
SELECT s.*, u.username as user_username, u.name as user_name, u.gender as user_gender, u.phone as user_phone, u.email as user_email, c.class_no, c.class_name FROM student s LEFT JOIN user u ON s.user_id = u.id LEFT JOIN class c ON s.class_id = c.id
AND s.student_no LIKE CONCAT('%', #{studentNo}, '%')
AND s.dormitory_id = #{dormitoryId}
AND s.class_id = #{classId}
ORDER BY s.student_no
